    function renderTree(){const host=byId('tree');const query=byId('tree-filter').value.trim().toLocaleLowerCase();const status=byId('status-filter').value;const priority=byId('priority-filter').value;const kind=byId('kind-filter').value;const label=byId('label-filter').value;const scope=state.scopeId&&treeIndex().byId.has(state.scopeId)?state.scopeId:null;renderFilterChips({query,status,priority,kind,label,scope});host.setAttribute('aria-busy',String(state.loadingMore));const progress=byId('tree-progress');if(progress){progress.hidden=!state.loadingMore;progress.textContent='Loading tickets '+state.items.length+' / '+state.total+' …';}if(!state.items.length){host.innerHTML='<div class="empty-list">'+(state.loadingMore?'Loading tickets …':state.treeError?'Tickets are not available right now.':'This project has no tickets yet. Create the first one with + Create, or let an agent run <code>plantool ticket create</code>.')+'</div>';return;}const html=[];if(query||status||priority||kind||label||scope){const matches=state.items.filter(ticket=>(!query||ticket.title.toLocaleLowerCase().includes(query))&&(!status||ticket.status===status)&&(!priority||ticket.priority===priority)&&(!kind||(ticket.kind||'task')===kind)&&(!label||(ticket.labels||[]).includes(label))&&(!scope||ticket.id===scope||ancestorsOf(ticket.id).some(a=>a.id===scope)));state.matchCount=matches.length;byId('filter-count')&&(byId('filter-count').textContent=matches.length+' of '+state.items.length+' tickets');if(!matches.length){host.innerHTML='<div class="empty-list">No tickets match these filters.'+(state.activeId?' The open ticket stays in the detail view.':'')+'</div>';return;}for(const ticket of matches.slice(0,state.filterLimit)){const path=ancestorsOf(ticket.id).map(a=>a.title).join(' › ');html.push(treeRow(ticket,{depth:0,path}));}if(matches.length>state.filterLimit)html.push('<button type="button" class="tree-more-inline" data-more-matches>Show '+Math.min(200,matches.length-state.filterLimit)+' more of '+(matches.length-state.filterLimit)+' remaining matches</button>');}else{const {children}=treeIndex();const stack=[{parent:null,depth:0,index:0}];let rendered=0;while(stack.length&&rendered<5000){const frame=stack[stack.length-1];const list=children.get(frame.parent)||[];const limit=state.branchLimit.get(frame.parent??'')||200;if(frame.index>=list.length||frame.index>=limit){if(list.length>limit&&frame.index>=limit)html.push('<div class="tree-item" style="--depth:'+Math.min(frame.depth,4)+'"><span class="tree-toggle-spacer" aria-hidden="true"></span><button type="button" class="tree-more-inline" data-more-children="'+esc(frame.parent??'')+'">Show '+Math.min(200,list.length-limit)+' more of '+(list.length-limit)+' remaining</button></div>');stack.pop();continue;}const ticket=list[frame.index++];html.push(treeRow(ticket,{depth:frame.depth}));rendered++;if(state.expanded.has(ticket.id)&&children.has(ticket.id))stack.push({parent:ticket.id,depth:frame.depth+1,index:0});}}host.innerHTML=html.join('');host.querySelectorAll('[data-ticket-id]').forEach(link=>link.addEventListener('click',event=>{if(event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;event.preventDefault();state.treeFocusId=link.dataset.ticketId;openTicket(link.dataset.ticketId,{push:true,keepFocus:true});}));host.querySelectorAll('[data-toggle-id]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.toggleId;if(state.expanded.has(id))state.expanded.delete(id);else state.expanded.add(id);renderTree();host.querySelector('[data-toggle-id="'+CSS.escape(id)+'"]')?.focus();}));host.querySelectorAll('[data-more-children]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.moreChildren;state.branchLimit.set(key,(state.branchLimit.get(key)||200)+200);renderTree();}));host.querySelector('[data-more-matches]')?.addEventListener('click',()=>{state.filterLimit+=200;renderTree();});rovingTree(host);}
    async function loadTree({append=false}={}){const generation=++state.treeGeneration;byId('tree').setAttribute('aria-busy','true');byId('tree-error').hidden=true;state.treeError=null;byId('tree-more').hidden=true;const pageSize=2000;try{const first=await api('/api/tree?limit='+pageSize+'&offset=0');if(generation!==state.treeGeneration)return;const firstLoad=!state.items.length&&!state.treeLoaded;state.items=first.items||[];state.total=first.total||0;state.index=null;if(firstLoad){const roots=state.items.filter(ticket=>ticket.depth===0);if(roots.length<=10)for(const ticket of roots)if(ticket.childCount)state.expanded.add(ticket.id);}state.loadingMore=state.items.length<state.total;updateCounts();statusOptions();priorityOptions();if(state.activeId)expandTo(state.activeId);renderTree();while(state.items.length<state.total){const page=await api('/api/tree?limit='+pageSize+'&offset='+state.items.length);if(generation!==state.treeGeneration)return;if(!page.items.length)break;state.items=state.items.concat(page.items);state.total=page.total;state.index=null;if(state.activeId)expandTo(state.activeId);renderTree();}state.loadingMore=false;state.treeLoaded=true;statusOptions();priorityOptions();labelOptions();renderTree();if(state.view==='overview')renderSummary();if(state.view==='board')renderBoard();}catch(error){if(generation!==state.treeGeneration)return;state.loadingMore=false;byId('tree').setAttribute('aria-busy','false');state.treeError=error.message;byId('tree-error').textContent='The ticket list could not be loaded: '+error.message;byId('tree-error').hidden=false;byId('tree-more').textContent='Retry loading tickets';byId('tree-more').hidden=false;renderTree();}}
