        const form=byId('edit-ticket-form');
        byId('comment-form').addEventListener('submit',async event=>{event.preventDefault();const area=byId('comment-body');const text=area.value.trim();if(!text){byId('comment-state').textContent='Write something first.';return;}byId('comment-submit').disabled=true;try{await api('/api/tickets/'+encodeURIComponent(id)+'/comments',{method:'POST',body:JSON.stringify({body:text,author:'person'})});await openTicket(id,{});}catch(error){byId('comment-state').textContent='The comment was not saved: '+error.message;byId('comment-submit').disabled=false;}});byId('edit-ticket-button').addEventListener('click',()=>{form.hidden=false;byId('edit-ticket-button').hidden=true;byId('edit-title').focus();});
